  "signal_basis": {
    "component_id": "C012_SIGNAL_BASIS",
    "value": "The operation permits only isolated, resource-capped tests or approved overnight trials, without requesting customer reruns during business hours.",
    "scope": "An explicit restriction on test execution, rather than an empirical conclusion from export timings.",
    "provenance": {
      "refs": [
